package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Frequency_addValue_TriageGen5Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }







    @Test
    public void testAddValueWithObjectComparable() {
        // Testing the deprecated addValue(Object v) which casts to Comparable
        String val = "test";
        frequency.addValue(val);
        Assert.assertEquals(1L, frequency.getCount(val));
        Assert.assertEquals(1.0, frequency.getPct(val), 1e-9);
    }








}

