public class Frequency_addValue_TriageGen5Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }









    @Test(expected = ClassCastException.class)
    public void testAddValueWithNonComparableObject() {
        // This object does not implement Comparable, should trigger ClassCastException 
        // inside the deprecated addValue(Object v) method due to (Comparable<?>) v
        Object nonComparable = new Object();
        frequency.addValue(nonComparable);
    }






}

