public class Frequency_addValue_TriageGen5Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }











    @Test
    public void testAddValueMultipleTimes() {
        frequency.addValue(1);
        frequency.addValue(1);
        frequency.addValue(2);

        Assert.assertEquals(2L, frequency.getCount(1));
        Assert.assertEquals(1L, frequency.getCount(2));
        Assert.assertEquals(3L, frequency.getSumFreq());
    }




}

