package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Frequency_addValue_TriageGen5Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }















    @Test
    public void testAddValueAndGetCumulative() {
        frequency.addValue(1);
        frequency.addValue(2);
        frequency.addValue(3);

        // Frequency: 1:1, 2:1, 3:1
        // Cumulative: 1:1, 2:2, 3:3
        Assert.assertEquals(1L, frequency.getCumFreq(1));
        Assert.assertEquals(2L, frequency.getCumFreq(2));
        Assert.assertEquals(3L, frequency.getCumFreq(3));
    }
}
